import { DataTable } from "./data-table"
import { columns, Document } from "./columns"

// Use same fetching logic or move to a separate utility if needed
async function getDocuments() {
    const baseUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000';
    // Note: For pagination/filtering to be server-side, you'd pass params here.
    // For client-side (Tanstack Table default), we fetch all and let the client handle it.
    const res = await fetch(`${baseUrl}/api/documents`, { cache: 'no-store' });

    if (!res.ok) {
        throw new Error('Failed to fetch documents');
    }

    return res.json();
}

export async function DocumentsTable() {
    const documents: Document[] = await getDocuments();

    return (
        <DataTable columns={columns} data={documents} />
    )
}
